import PohAva from '@ui-kit/Ava';

import { IBaseClub } from '../@types/clubs.types';

interface IClubListItemProps {
  club: IBaseClub;
}

const ClubListItem = ({ club }: IClubListItemProps) => {
  return (
    <div className="d-flex horizontal-gapped">
      <PohAva src={club.logo} alt={club.code} />
      {club.name}
    </div>
  );
};

export default ClubListItem;
